s=>{
    s.vertexShader='varying vec3 vFmP;varying vec3 vFmN;\n'+s.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n'+
      'vFmP=transformed*vec3(length(modelMatrix[0].xyz),length(modelMatrix[1].xyz),length(modelMatrix[2].xyz));vFmN=normal;');
    const tri=['#ifdef USE_MAP','vec3 fw=pow(abs(vFmN),vec3(6.));fw/=(fw.x+fw.y+fw.z+1e-4);',
      'vec4 fmT=texture2D(map,vFmP.zy*.3)*fw.x+texture2D(map,vFmP.xz*.3)*fw.y+texture2D(map,vFmP.xy*.3)*fw.z;',
      'diffuseColor*=fmT;float fmL=dot(fmT.rgb,vec3(.33));','#endif'].join('\n');
    const rough=['#include <roughnessmap_fragment>','#ifdef USE_MAP','roughnessFactor=clamp(roughnessFactor*(1.35-fmL*1.1),.2,1.);','#endif'].join('\n');
    s.fragmentShader='varying vec3 vFmP;varying vec3 vFmN;\n'+s.fragmentShader.replace('#include <map_fragment>',tri).replace('#include <roughnessmap_fragment>',rough);
  }

